import tempfile, subprocess
from pathlib import Path
from videopipeline.models import VisualSegment, TimelineSchedule, SourceClass
from videopipeline.stages.stage4_render.nvenc_engine import NvencRenderEngine
root=Path(tempfile.mkdtemp(prefix='xp004-accept-'))
def ff(*args):
    subprocess.run(['ffmpeg','-y','-v','error',*map(str,args)],check=True)
def video(name,color):
    p=root/name; ff('-f','lavfi','-i',f'color=c={color}:s=320x180:r=30','-t','2','-c:v','libx264','-pix_fmt','yuv420p',p); return p
def image(name,color):
    p=root/name; ff('-f','lavfi','-i',f'color=c={color}:s=320x180','-frames:v','1',p); return p
sources={'gv':video('generated.mp4','red'),'gv2':video('generated2.mp4','yellow'),'stock':video('stock.mp4','blue'),'original':video('original.mp4','green'),'image':image('generated.png','magenta'),'image2':image('generated2.png','cyan')}
audio=root/'silence.wav'; ff('-f','lavfi','-i','anullsrc=r=48000:cl=stereo','-t','8','-c:a','pcm_s16le',audio)
ass=root/'empty.ass'; ass.write_text('[Script Info]\\nScriptType: v4.00+\\nPlayResX: 1920\\nPlayResY: 1080\\n[V4+ Styles]\\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\\nStyle: Default,Arial,24,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,1,1,0,2,10,10,10,1\\n[Events]\\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\\n')
formats={
'F1':[('chap1_opening','gv','GENERATED_VIDEO'),('slideshow','image','GENERATED_IMAGE')],
'F2':[('chap1_opening','gv','GENERATED_VIDEO'),('stock','stock','STOCK_ONLINE'),('veo_ai','gv2','GENERATED_VIDEO')],
'F3':[('slideshow','image','GENERATED_IMAGE'),('slideshow','image2','GENERATED_IMAGE')],
'F4':[('f1_framed','original','ORIGINAL_REUP_VIDEO'),('stock','stock','STOCK_ONLINE')],
'F5':[('stock','stock','STOCK_ONLINE'),('stock','stock','STOCK_ONLINE')]}
for fmt, rows in formats.items():
    segs=[]
    for i,(typ,key,cls) in enumerate(rows):
        segs.append(VisualSegment(i,0,2,typ,sources[key],source_class=SourceClass(cls),asset_id=key))
    sched=TimelineSchedule(root,audio,2,segs,fmt)
    out=root/f'{fmt}.mp4'
    try:
        NvencRenderEngine(root/f'work-{fmt}').render_master_video(sched,ass,out,format=fmt)
        print(fmt,'accepted',out.stat().st_size)
    except Exception as e: print(fmt,'FAILED',repr(e))
print('MEDIA_ROOT',root)
'@ | python -"

